import math

def tau(n):
    """Calculates the number of positive divisors of n, tau(n)."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates the number of positive divisors of n other than 1 and itself."""
    if n <= 0:
        return -1 # Should not happen based on problem constraints
    tau_n = tau(n)
    # d(n) = tau(n) - 2, but must be non-negative.
    return max(0, tau_n - 2)

# Parameters
N_MAX = 5000
OFFSET = 735

min_a = float('inf')
best_n = None

print(f"Starting search for n up to {N_MAX}...")

for n in range(1, N_MAX + 1):
    n_plus_offset = n + OFFSET

    a_n = d(n)
    a_n_plus_offset = d(n_plus_offset)

    if a_n == a_n_plus_offset:
        a = a_n
        if a < min_a:
            min_a = a
            best_n = n
            # Since we are iterating n in increasing order, 
            # if we find a smaller 'a', we update.
            # If we find a match for the current min_a, we keep the smallest n (implicitly done by the loop structure).

# Output results
if best_n is not None:
    print("\n--- Results ---")
    print(f"Smallest non-negative integer a found: {min_a}")
    print(f"Corresponding n: {best_n}")
else:
    print("\nNo solutions found in the range.")

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

# 735 = 3 * 5 * 7^2
print(f"Prime factors of 735: {prime_factorization(735)}")

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# List of divisor pairs (A, B) where A*B = 735 and A < B
divisors = []
for i in range(1, int(735**0.5) + 1):
    if 735 % i == 0:
        d1 = i
        d2 = 735 // i
        divisors.append((d1, d2))

print("\nDivisor pairs (A, B):")
for d1, d2 in divisors:
    print(f"({d1}, {d2})")

print("\nChecking cases:")
solutions = []
for A, B in divisors:
    # Since 735 is odd, A and B must be odd, so A+B and B-A are even.
    p1 = (B - A) / 2
    p2 = (A + B) / 2

    # We only check pairs where A and B are both odd, which is true for all factor pairs of 735.
    if is_prime(int(p1)) and is_prime(int(p2)):
        solutions.append((p1, p2))
        print(f"Found solution: p1={int(p1)}, p2={int(p2)}")

if not solutions:
    print("\nNo solution found where both p1 and p2 are prime.")

import math

def count_divisors(k):
    if k <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(k)) + 1):
        if k % i == 0:
            if i * i == k:
                count += 1
            else:
                count += 2
    return count

# d(n) is the number of positive divisors of n other than 1 and itself.
# d(n) = tau(n) - 2, where tau(n) is the total number of divisors.
# We are looking for the smallest n such that d(n) = d(n+735) = 1.
# This means tau(n) = 3 and tau(n+735) = 3, i.e., n and n+735 are squares of primes.

N_MAX = 10000
target_a = 1
smallest_n = -1

for n in range(1, N_MAX + 1):
    tau_n = count_divisors(n)
    d_n = tau_n - 2

    if d_n == target_a:
        n_plus_735 = n + 735
        tau_n_plus_735 = count_divisors(n_plus_735)
        d_n_plus_735 = tau_n_plus_735 - 2

        if d_n_plus_735 == target_a:
            smallest_n = n
            break

print(f"Smallest n found such that d(n) = d(n+735) = 1 up to {N_MAX}: {smallest_n}")
